import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/68-浪漫旅行中的酒店风波.md","filePath":"books/attached/68-浪漫旅行中的酒店风波.md","lastUpdated":1794316978000}'),n={name:"books/attached/68-浪漫旅行中的酒店风波.md"};function _(d,a,c,l,i,p){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"浪漫旅行中的酒店风波",tabindex:"-1"},[s("浪漫旅行中的酒店风波 "),e("a",{class:"header-anchor",href:"#浪漫旅行中的酒店风波","aria-label":'Permalink to "浪漫旅行中的酒店风波"'},"​")],-1),e("p",null,"24岁的苏珊和28岁的保罗决定去佛蒙特来一场前所未有的浪漫之旅。到那里后，他们备选了两间中意的民宿房间，两家同样舒适，主人也非常热情。而两个房间的区别在于，一家的房间里是两张单人床，而另一家则是一张双人大床。保罗想定两张单人床那间，因为那间房的窗外景色更美。而苏珊当然是青睐大床那间，她根本不能想象，一场浪漫的旅行到头来两人却要分床睡。保罗就对苏珊有些不满道：“我们每天都同枕而眠，这有什么大不了的吗？起码分床睡，我们可以看到更美的景色！”苏珊对于自己在夜晚如此依恋保罗这件事，感到有些羞愧。但她仍旧不能接受一场浪漫旅行之中，两人要分床而睡。双方都不肯让步，两人的争吵令美好的周末就这样快要泡汤。",-1),e("p",null,"那么，怎样看待这场争执呢？从表面上来看，只是对待酒店房间的品位不同而已，苏珊的坚持好像有些不可理喻了。但是你要知道，保罗在上床睡觉之前不愿意拥抱苏珊，这让苏珊非常困惑，并从保罗的所作所为里，感到了深深的抗拒。苏珊明白，要是选择两张单人床的标准间，保罗在亲热过后会自己到另一张床睡觉。了解了这些信息，苏珊看起来就不那么无理取闹了。显然，她的顾虑在于，最基本的亲密需求得不到满足。",-1)])])}const h=t(n,[["render",_]]);export{f as __pageData,h as default};
